**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    int maxDl = 0, maxStart = 0;
    long long maxSuma = 0;
    int curDl = 0, curStart = 0;
    long long curSuma = 0;

    for (int i = 0; i < n; i++) {
        if (T[i] % 3 == 0) {
            if (curDl == 0) curStart = i;
            curDl++;
            curSuma += T[i];
        } else {
            if (curDl > maxDl) {
                maxDl = curDl;
                maxStart = curStart;
                maxSuma = curSuma;
            }
            curDl = 0;
            curSuma = 0;
        }
    }
    if (curDl > maxDl) {
        maxDl = curDl;
        maxStart = curStart;
        maxSuma = curSuma;
    }

    cout << "a) Dlugosc: " << maxDl
         << ", pozycja poczatkowa: " << maxStart + 1 << endl;
    cout << "b) Suma: " << maxSuma << endl;
    cout << "c) Elementy:";
    for (int i = maxStart; i < maxStart + maxDl; i++)
        cout << " " << T[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Wzorzec current/max z warunkiem jednoelementowym (`% 3 == 0`). Oproz dlugosci sledzony jest tez suma biezacego podciagu.

